// wf.listing.extract > "Call input"
// Input: the listing's text, jurisdiction and today's date there, and the Text service's answer.
// Output: the wf.llm.call input for P3 (active version unless the caller asks for one).
const s = $('Start').first().json;
const c = $('Context').first().json;
return [{ json: { prompt: 'P3_listing_extractor', version: s.version ?? null, model: s.model || null,
  vars: { message: c.text, jurisdiction: c.jurisdiction_code, today: c.today, default_currency: (c.ctx || {}).default_currency },
  meta: { listing_id: c.listing_id } } }];

// wf.listing.extract > "Check listing"
// Deterministic checks after P3 (spec 9.4, D-076, D-077): plausible rent ranges (lib/listing_check.js),
// main units to minor units with the currency exponent, one currency per listing, and issue codes
// for what the owner must confirm. The model's answer and the checked fields are both kept in
// app.listings.extraction; the agent step records the call without the listing text.
// Deterministic checks after P3 (spec 9.4 post-validation, D-076). The model gives amounts in main
// units. A rent outside the plausible range for its currency (main units per month; weekly rents
// are compared as 52/12 of a week) is set to null with an issue: this catches scale errors such as
// 1,225,000 dinars for 1,225 (spec 3.1). A deposit is checked against the same range; 0 is
// accepted. Issues added here are codes, never sentences (spec 17.1).
//
// out: the validated P3 output; ranges: {currency: [min, max]} from the setting listing.rent_range;
// fallbackCurrency: the jurisdiction's currency, used when an amount has none.
// Returns {fields, issues, changed}: fields is a copy of out with the checks applied.
function checkListing(out, ranges, fallbackCurrency) {
  if (!out || typeof out !== 'object') return { fields: out, issues: [], changed: [] };
  const f = JSON.parse(JSON.stringify(out));
  const issues = [];
  const changed = [];
  const R = ranges || {};
  if (f.rent_amount !== null && f.rent_amount !== undefined) {
    if (!f.rent_currency) { f.rent_currency = fallbackCurrency || null; issues.push('rent_currency_assumed'); changed.push('rent_currency'); }
    if (!f.rent_period) { f.rent_period = 'month'; changed.push('rent_period'); }
    if (!f.rent_scope) { f.rent_scope = 'unknown'; changed.push('rent_scope'); }
    const r = R[f.rent_currency];
    const monthly = f.rent_period === 'week' ? (f.rent_amount * 52) / 12 : f.rent_amount;
    if (!r) issues.push('rent_range_unknown');
    else if (monthly < r[0] || monthly > r[1]) {
      issues.push('rent_out_of_range');
      f.rent_amount = null; f.rent_currency = null; f.rent_period = null; f.rent_scope = null;
      changed.push('rent_amount');
    }
  }
  if (f.deposit_amount !== null && f.deposit_amount !== undefined) {
    if (!f.deposit_currency) { f.deposit_currency = f.rent_currency || fallbackCurrency || null; changed.push('deposit_currency'); }
    const r = R[f.deposit_currency];
    if (r && f.deposit_amount !== 0 && (f.deposit_amount < r[0] || f.deposit_amount > r[1])) {
      issues.push('deposit_out_of_range');
      f.deposit_amount = null; f.deposit_currency = null;
      changed.push('deposit_amount');
    }
  }
  if (Array.isArray(f.amenities)) f.amenities = [...new Set(f.amenities)].sort();
  return { fields: f, issues, changed };
}

// Main units to minor units with the currency exponent (app.currencies), for storage.
function toMinorUnits(amount, currency, exponents) {
  if (amount === null || amount === undefined || !currency || !exponents ||
      !Object.prototype.hasOwnProperty.call(exponents, currency)) return null;
  const n = Number(amount);
  return Number.isFinite(n) && n >= 0 ? Math.round(n * Math.pow(10, Number(exponents[currency]))) : null;
}

if (typeof module !== 'undefined') module.exports = { checkListing, toMinorUnits };

const r = $input.first().json;
const c = $('Context').first().json;
const ctx = c.ctx || {};
const tr = $('Text analysis').first().json || {};
const tb = tr.body && typeof tr.body === 'object' ? tr.body : null;
const step = { agent: 'A1_extract', prompt_version_id: r.prompt_version_id || null, model: r.model || null,
  input: { chars: Array.from(String(c.text || '')).length, jurisdiction: c.jurisdiction_code },
  output: r.ok ? r.output : { error_code: r.error_code }, latency_ms: r.latency_ms, tokens_in: r.tokens_in || 0,
  tokens_out: r.tokens_out || 0, error: r.ok ? null : `${r.error_code}${r.detail ? ': ' + String(r.detail).slice(0, 200) : ''}` };
if (!r.ok) {
  return [{ json: { ok: false, store: false, listing_id: c.listing_id, transient: !!r.call_error,
    error: r.call_error ? 'model unavailable' : `extraction failed: ${r.error_code}`, steps: [step] } }];
}
const check = checkListing(r.output, ctx.rent_ranges || {}, ctx.default_currency || null);
const x = check.fields;
const issues = [...check.issues];
const exps = ctx.currencies || {};
let currency = x.rent_currency || null;
let rent_minor = toMinorUnits(x.rent_amount, x.rent_currency, exps);
if (x.rent_amount !== null && rent_minor === null) { issues.push('rent_currency_unknown'); currency = null; }
let deposit_minor = toMinorUnits(x.deposit_amount, x.deposit_currency, exps);
if (deposit_minor !== null && currency && x.deposit_currency !== currency) { issues.push('deposit_currency_differs'); deposit_minor = null; }
if (deposit_minor !== null && !currency) currency = x.deposit_currency;
if (rent_minor === null) issues.push('rent_missing');
else if (x.rent_scope === 'whole_flat' || x.rent_scope === 'unknown') issues.push(`rent_scope_${x.rent_scope}`);
const pii = tb && tb.pii ? tb.pii.counts || {} : null;
if (pii && ((pii.PHONE || 0) + (pii.EMAIL || 0)) > 0) issues.push('contact_details_in_text');
const fields = { kind: x.kind, rent_minor, currency: rent_minor === null && deposit_minor === null ? null : currency,
  rent_period: rent_minor === null ? null : x.rent_period, rent_scope: rent_minor === null ? null : x.rent_scope,
  deposit_minor, bills_included: x.bills_included, available_from: x.available_from, bedrooms: x.bedrooms,
  furnished: x.furnished, amenities: x.amenities || [], house_rules: x.house_rules || {}, city: x.city, neighbourhood: x.neighbourhood };
const extraction = { prompt_version_id: r.prompt_version_id, model: r.model, model_output: r.output, address_text: x.address_text,
  issues: [...new Set(issues)], model_issues: x.issues || [], field_confidence: x.field_confidence || {},
  checks_changed: check.changed, language: tb ? tb.language : null, pii_counts: pii };
return [{ json: { ok: true, store: true, listing_id: c.listing_id, steps: [step],
  params: [c.listing_id, JSON.stringify({ fields, description_lang: tb ? tb.language.language : null, extraction })],
  summary: { issues: extraction.issues, rent_minor, currency: fields.currency, rent_scope: fields.rent_scope } } }];

// wf.listing.extract > "Result": {ok, status, listing_id, issues, transient, error, steps}.
// status: extracted, no_text (nothing to extract), failed (model or storage); transient failures are
// retried by the analyze job (spec 5.6).
const c = $('Context').first().json;
if (!c.text || !String(c.text).trim()) {
  return [{ json: { ok: true, status: 'no_text', listing_id: c.listing_id, issues: [], transient: false, error: null, steps: [] } }];
}
const x = $('Check listing').first().json;
if (!x.ok) return [{ json: { ok: false, status: 'failed', listing_id: x.listing_id, issues: [], transient: x.transient, error: x.error, steps: x.steps } }];
const st = ($('Store extraction').first().json || {}).r || {};
if (!st.ok) {
  return [{ json: { ok: false, status: 'failed', listing_id: x.listing_id, issues: [], transient: false,
    error: `store: ${st.error_code || 'no answer'}${st.message ? ' (' + st.message + ')' : ''}`, steps: x.steps } }];
}
return [{ json: { ok: true, status: 'extracted', listing_id: x.listing_id, ...x.summary, transient: false, error: null, steps: x.steps } }];
